function validate([date1, date2]) {
  for (const date of [date1, date2]) {
    if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return 'Dates are written as YYYY-MM-DD.';
    const [year, month, day] = date.split('-').map(Number);
    if (year < 1971 || year > 2100) return 'Years are between 1971 and 2100.';
    if (month < 1 || month > 12) return 'The month is between 01 and 12.';
    const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    const length = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
    if (day < 1 || day > length) return `${date} is not a real date.`;
  }
  return null;
}

