function daysBetweenDates(date1, date2) {
  // Let the built-in calendar count milliseconds in UTC, where every day is exactly 86,400,000 ms long.
  const toTime = (date) => {
    const [year, month, day] = date.split('-').map(Number);
    return Date.UTC(year, month - 1, day);
  };
  return Math.abs(toTime(date1) - toTime(date2)) / 86400000;
}

