function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const first = Date.UTC(1971, 0, 1) / 86400000;
  const last = Date.UTC(2100, 11, 31) / 86400000;
  const format = (dayIndex) => new Date(dayIndex * 86400000).toISOString().slice(0, 10);
  // Interesting anchors: leap days, the non-leap 2100, year ends and the range limits.
  const anchors = ['1971-01-01', '2100-12-31', '2000-02-29', '2100-02-28', '2100-03-01', '1999-12-31', '2020-02-29', '1972-02-29', '2096-02-29', '2000-03-01']
    .map(d => Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10)) / 86400000);
  const pick = () => (rand() < 0.3 ? anchors[int(0, anchors.length - 1)] : int(first, last));
  const a = pick();
  const r = rand();
  let b;
  if (size === 'large' || r < 0.4) b = pick();
  else if (r < 0.55) b = a;
  else b = Math.min(last, Math.max(first, a + int(-40, 40)));
  return [format(a), format(b)];
}
